import{_ as e,o,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Building conditions","description":"Comparisons, AND/OR, and branches — expressions that return a boolean.","frontmatter":{"title":"Building conditions","description":"Comparisons, AND/OR, and branches — expressions that return a boolean."},"headers":[],"relativePath":"en/apptivescript/bedingungen.md","filePath":"en/apptivescript/bedingungen.md","lastUpdated":1787319236000}'),a={name:"en/apptivescript/bedingungen.md"};function s(r,t,d,l,c,h){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="building-conditions" tabindex="-1">Building conditions <a class="header-anchor" href="#building-conditions" aria-label="Permalink to &quot;Building conditions&quot;">​</a></h1><p>Three places in ApptiveGrid expect a <strong>condition</strong> — an expression that ultimately evaluates to true or false: a block&#39;s <a href="/en/seiten/sichtbarkeit">conditional visibility</a>, the transition between two Flow steps, and the filter.</p><p>This page shows the building blocks and how the three dialogs handle them.</p><h2 id="comparing" tabindex="-1">Comparing <a class="header-anchor" href="#comparing" aria-label="Permalink to &quot;Comparing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Example</th></tr></thead><tbody><tr><td>equal · not equal</td><td><code>fieldValue(&#39;status&#39;).isEqualTo(&#39;Open&#39;)</code></td></tr><tr><td>greater · less</td><td><code>fieldValue(&#39;quantity&#39;).greaterThan(10)</code></td></tr><tr><td>greater/less than or equal</td><td><code>fieldValue(&#39;quantity&#39;).greaterThanOrEqual(10)</code></td></tr><tr><td>contains</td><td><code>fieldValue(&#39;title&#39;).contains(&#39;Invoice&#39;)</code></td></tr><tr><td>begins with · ends with</td><td><code>fieldValue(&#39;number&#39;).beginsWith(&#39;INV-&#39;)</code></td></tr><tr><td>empty · not empty</td><td><code>fieldValue(&#39;orderNumber&#39;).isNotEmpty()</code></td></tr><tr><td>true · false</td><td><code>formValues.get(&#39;terms&#39;).isTrue()</code></td></tr><tr><td>before · after (date)</td><td><code>fieldValue(&#39;deadline&#39;).before(today())</code></td></tr><tr><td>list contains</td><td><code>fieldValue(&#39;tags&#39;).includesAnyOf(&#39;urgent&#39;)</code></td></tr></tbody></table><p>Which condition is allowed depends on the type of the value on the left — the full list by type is in the <a href="/en/referenz/apptivescript-funktionen">function reference</a>.</p><h2 id="combining-multiple-conditions" tabindex="-1">Combining multiple conditions <a class="header-anchor" href="#combining-multiple-conditions" aria-label="Permalink to &quot;Combining multiple conditions&quot;">​</a></h2><p>There are no keywords. <em>And</em> and <em>or</em> are functions layered on top of a condition:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;terms&#39;).isTrue())</span></span></code></pre></div><p>For more than two conditions, you keep chaining — the interface does the same:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a.logicalAnd(b).logicalAnd(c)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Meaning</th><th>Syntax</th></tr></thead><tbody><tr><td>and</td><td><code>.logicalAnd(…)</code></td></tr><tr><td>or</td><td><code>.logicalOr(…)</code></td></tr><tr><td>not</td><td><code>.isFalse()</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Mixing AND and OR within one rule</p><p>Technically it&#39;s allowed, but the interface can then no longer break the expression down into rows — you edit it only as a whole. Stick to <strong>one</strong> connector type per rule. If you need both, an extra step or an extra block is usually the clearer solution.</p></div><h2 id="branching-with-if" tabindex="-1">Branching with <code>if</code> <a class="header-anchor" href="#branching-with-if" aria-label="Permalink to &quot;Branching with `if`&quot;">​</a></h2><p><code>if</code> is the language&#39;s only branch. It sits <strong>after</strong> the condition and returns one of two values:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;quantity&#39;).smallerThan(5).if(&#39;reorder&#39;, &#39;ok&#39;)</span></span></code></pre></div><p>That makes <code>if</code> well suited to Formula columns — for example, a traffic-light status as text. For visibility and Flow transitions you don&#39;t need it: the condition alone is enough there.</p><h2 id="conditional-visibility-of-blocks" tabindex="-1">Conditional visibility of blocks <a class="header-anchor" href="#conditional-visibility-of-blocks" aria-label="Permalink to &quot;Conditional visibility of blocks&quot;">​</a></h2><p>The simple selection of <strong>Field</strong>, <strong>Condition</strong>, and <strong>Value</strong> covers eight conditions and writes the expression for you:</p><table tabindex="0"><thead><tr><th>Selection</th><th>Expression generated</th></tr></thead><tbody><tr><td>is empty · is not empty</td><td><code>formValues.get(&#39;key&#39;).isEmpty()</code> · <code>.isNotEmpty()</code></td></tr><tr><td>is true · is false</td><td><code>.isTrue()</code> · <code>.isFalse()</code></td></tr><tr><td>is equal · is not equal</td><td><code>.isEqualTo(&#39;value&#39;)</code> · <code>.isNotEqualTo(&#39;value&#39;)</code></td></tr><tr><td>is greater than · is less than</td><td><code>.greaterThan(5)</code> · <code>.smallerThan(5)</code></td></tr></tbody></table><p><em>is true</em> and <em>is false</em> only appear for a Checkmark block. Numbers are inserted without quotation marks, everything else with them.</p><p>The <strong>Advanced</strong> section below shows the expression and lets you edit it. As long as it matches the simple form, both views stay in sync; as soon as you combine something, only the text field continues to work.</p><div class="tip custom-block"><p class="custom-block-title">Try it out in the editor</p><p>Next to the visibility rule, the editor shows <strong>Currently visible</strong> or <strong>Currently hidden</strong> — for the values currently in the input blocks. Enter test values and watch it switch. That&#39;s the fastest check, without publishing anything.</p></div><p>→ <a href="/en/seiten/sichtbarkeit">Conditional visibility</a></p><h2 id="flow-transitions" tabindex="-1">Flow transitions <a class="header-anchor" href="#flow-transitions" aria-label="Permalink to &quot;Flow transitions&quot;">​</a></h2><p>The <strong>Only continue if …</strong> dialog on a connection between two steps builds the condition from rows:</p><ol><li>At the top, choose <strong>All conditions met (AND)</strong> or <strong>At least one condition (OR)</strong>.</li><li>Each row consists of <strong>Select value …</strong>, <strong>Select condition …</strong>, and a comparison value.</li><li><strong>Add condition</strong> adds a row, the cross removes it.</li></ol><div class="tip custom-block"><p class="custom-block-title">Choose the value first, then the condition</p><p>The list of conditions depends on the <strong>type of the left-hand value</strong>. Pick the value first, and only the matching conditions remain — for a date, for instance, <em>before</em> and <em>after</em>.</p><p>The dialog gets the type from the last <strong>test run</strong>. Without a test run it&#39;s <em>Undefined</em>, and the list shows every condition for every type. → <a href="/en/flows/testen">Testing Flows</a></p></div><p>In the rows, you don&#39;t add <strong>any</strong> quotation marks: for text and dates, the dialog adds them for you.</p><p>Under <strong>Advanced logic</strong> is the full expression as text. Write connections there that the rows can&#39;t express — and the normal rules apply there too, including quotation marks. The hint in the dialog explains when the input takes effect:</p><blockquote><p><em>Applied when you leave the field or click Save.</em></p></blockquote><p>Two messages can appear:</p><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><em>Unrecognized expression</em></td><td>This row can&#39;t be read as value-condition-value — edit it under <em>Advanced logic</em></td></tr><tr><td><em>This expression mixes AND/OR …</em></td><td>The rows are locked; only the full expression applies now</td></tr></tbody></table><p>→ <a href="/en/flows/router-und-parallel">Router and Parallel</a></p><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>In a <strong>View</strong>, you build filters exclusively through the interface — field, condition, value. ApptiveGrid translates that into an expression itself; there&#39;s no input field for custom expressions there. → <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, sorting, grouping</a></p><p>It&#39;s different in a <strong>Flow step with a filter</strong>: there, the value selector additionally offers <strong>Expression</strong>. That lets you compare a field not against a fixed value, but against a computed one — for example, the result of a previous step.</p><div class="warning custom-block"><p class="custom-block-title">A condition that doesn&#39;t work out filters the entry away</p><p>If a filter expression produces an error, nothing, or something other than a boolean, the entry is treated as <strong>not matching</strong> — it disappears from the result. An empty list is therefore a typical sign of a broken expression, not necessarily of missing data.</p></div><h2 id="common-conditions" tabindex="-1">Common conditions <a class="header-anchor" href="#common-conditions" aria-label="Permalink to &quot;Common conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Condition</th></tr></thead><tbody><tr><td>Extra field only for &quot;Other&quot;</td><td><code>formValues.get(&#39;category&#39;).isEqualTo(&#39;Other&#39;)</code></td></tr><tr><td>Range from age 18</td><td><code>formValues.get(&#39;age&#39;).greaterThan(17)</code></td></tr><tr><td>Continue only with consent</td><td><code>formValues.get(&#39;terms&#39;).isTrue()</code></td></tr><tr><td>Two conditions at once</td><td><code>formValues.get(&#39;age&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;terms&#39;).isTrue())</code></td></tr><tr><td>Only when a field is filled in</td><td><code>step(&#39;&lt;step id&gt;&#39;).output.get(&#39;email&#39;).isNotEmpty()</code></td></tr><tr><td>Overdue entries</td><td><code>fieldValue(&#39;&lt;deadline&gt;&#39;).before(today())</code></td></tr><tr><td>Everything except one status</td><td><code>fieldValue(&#39;&lt;status&gt;&#39;).isNotEqualTo(&#39;Done&#39;)</code></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptivescript/editor">The expression editor</a> — token view, picker, sample result</li><li><a href="/en/apptivescript/werte-referenzieren">Referencing values</a> — what an expression starts with</li><li><a href="/en/referenz/apptivescript-funktionen">Function reference</a> — every function by type</li><li><a href="/en/referenz/filterbedingungen">Filter conditions</a> — the interface&#39;s conditions at a glance</li></ul>',42)])])}const g=e(a,[["render",s]]);export{u as __pageData,g as default};
